const TRACK_COLORS = ['red', 'blue'];

const buildGraphForColor = (tracks, colors, targetColor) => {
    const graph = {};

    for (let trackIndex = 0; trackIndex < tracks.length; trackIndex++) {
        if (colors[trackIndex] !== targetColor) continue;

        const [stationOne, stationTwo] = tracks[trackIndex];

        const stationOneInGraph = graph.hasOwnProperty(stationOne);
        const stationTwoInGraph = graph.hasOwnProperty(stationTwo);

        if (!stationOneInGraph) graph[stationOne] = [];
        if (!stationTwoInGraph) graph[stationTwo] = [];

        graph[stationOne].push(stationTwo);
        graph[stationTwo].push(stationOne);
    }

    return graph;
};

// CONTRACT for canReachStation(graph, curStation, destination, visited):
//     when this call returns, it returns true if the search can get
//     from `curStation` to `destination` along this graph's tracks,
//     and false otherwise. Every station it explores goes into the
//     visited set, so no station is ever explored twice.
//     If `curStation` is already in the visited set it returns false —
//     an earlier call is already exploring from there.
const canReachStation = (graph, curStation, destination, visited) => {
    // Base cases
    if (curStation === destination) return true;

    if (visited.has(curStation)) return false;

    // Process node
    visited.add(curStation);

    // Recurse on neighbors
    const stationInGraph = graph.hasOwnProperty(curStation);
    if (!stationInGraph) return false;

    const neighbors = graph[curStation];

    for (const neighbor of neighbors) {
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, it tells us whether
        // `destination` can be reached from `neighbor`. Trust it, do not
        // trace it. If any neighbor's answer is true, a path through that
        // neighbor exists, so returning true keeps this function's
        // contract; if every answer is false, returning false keeps it too.
        const reachable = canReachStation(graph, neighbor, destination, visited);

        if (reachable) return true;
    }

    return false;
};

const canRideOneColor = (n, tracks, colors, source, destination) => {
    if (source === destination) return true;

    // The whole trip must stay on one line, so we try each color as
    // its own separate graph and check reachability inside it.
    for (const color of TRACK_COLORS) {
        const graph = buildGraphForColor(tracks, colors, color);
        const visited = new Set();

        // The recursive leap of faith: trust the contract. When this
        // call returns, `reachable` tells us whether `destination` can be
        // reached from `source` using only this color's tracks. We do not
        // trace inside; we just use the answer, then try the other color
        // if needed.
        const reachable = canReachStation(graph, source, destination, visited);

        if (reachable) return true;
    }

    return false;
};

