// CONTRACT for clusterContainsWell(graph, village, visited, villagesWithWells):
//     when this call returns, `village` and every village reachable
//     from it is in the visited set, and the returned value is true
//     if any village in that group has a well, false otherwise.
const clusterContainsWell = (graph, village, visited, villagesWithWells) => {
    // Base cases
    if (visited.has(village)) return false;

    // Process node
    visited.add(village);

    let foundWell = villagesWithWells.has(village);

    // Recurse on neighbors
    const villageInGraph = graph.hasOwnProperty(village);
    if (!villageInGraph) return foundWell;

    const neighbors = graph[village];

    for (const neighbor of neighbors) {
        // We keep walking even after finding a well so the whole
        // cluster gets marked visited exactly once.
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, `neighbor` and everything
        // reachable from it is in visited, and it reports whether it found
        // a well there. Trust it, do not trace it. This function already
        // put `village` into visited and checked it for a well; each
        // neighbor's guaranteed answer covers the rest of the cluster —
        // exactly this function's contract, kept.
        const wellInNeighborArea = clusterContainsWell(
            graph,
            neighbor,
            visited,
            villagesWithWells,
        );

        if (wellInNeighborArea) foundWell = true;
    }

    return foundWell;
};

const countWellsToDig = (n, paths, wells) => {
    const graph = buildGraph(paths);
    const villagesWithWells = new Set(wells);

    let wellsToDig = 0;
    const visited = new Set();

    for (let village = 0; village < n; village++) {
        if (visited.has(village)) continue;

        // The recursive leap of faith: trust the contract. When this
        // call returns, this entire cluster is in visited — the loop can
        // never start here again — and `clusterHasWell` tells us if the
        // cluster already has a well. We do not trace inside; we just use
        // the answer to decide whether one new well is needed.
        const clusterHasWell = clusterContainsWell(
            graph,
            village,
            visited,
            villagesWithWells,
        );

        if (clusterHasWell) continue;

        wellsToDig++;
    }

    return wellsToDig;
};

