const NO_CALLER = -1;
const STARTING_DAY = 0;

const buildCallTree = (caller) => {
    const callTree = {};

    for (let person = 0; person < caller.length; person++) {
        const personCaller = caller[person];

        if (personCaller === NO_CALLER) continue;

        const callerInTree = callTree.hasOwnProperty(personCaller);
        if (!callerInTree) callTree[personCaller] = [];

        callTree[personCaller].push(person);
    }

    return callTree;
};

// CONTRACT for countInformedInTime(callTree, waitDays, person, dayHeard, deadline):
//     when this call returns, the returned value is how many people
//     in `person`'s branch of the call tree (including `person`) hear
//     the news on or before day `deadline`, given that `person` hears
//     it on day `dayHeard`.
const countInformedInTime = (callTree, waitDays, person, dayHeard, deadline) => {
    // Base case: wait times are never negative, so if this person is
    // already past the deadline, everyone further down the chain is too.
    if (dayHeard > deadline) return 0;

    // Process node
    let informedCount = 1;

    // Recurse on neighbors
    const personMakesCalls = callTree.hasOwnProperty(person);
    if (!personMakesCalls) return informedCount;

    const dayOfCalls = dayHeard + waitDays[person];
    const listeners = callTree[person];

    for (const listener of listeners) {
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, it hands back how many
        // people in `listener`'s branch hear the news by the deadline.
        // Trust it, do not trace it. The 1 counted for `person` + each
        // listener's guaranteed count = exactly this function's contract.
        informedCount += countInformedInTime(
            callTree,
            waitDays,
            listener,
            dayOfCalls,
            deadline,
        );
    }

    return informedCount;
};

const countInformedByDeadline = (n, headId, caller, waitDays, deadline) => {
    const callTree = buildCallTree(caller);

    // The recursive leap of faith: trust the contract. When this
    // call returns, its value is how many people in the whole family
    // hear the news on or before day `deadline`. We do not trace
    // inside; we just return that number.
    return countInformedInTime(callTree, waitDays, headId, STARTING_DAY, deadline);
};

