// CONTRACT for getTrainLength(yard, row, col, visited):
//     when this call returns, every train car connected to
//     (`row`, `col`) is in the visited set, and the returned value is
//     how many cars this call put there. If (`row`, `col`) is not a
//     fresh train car, it returns 0 and nothing new goes in.
const getTrainLength = (yard, row, col, visited) => {
    // Base cases
    if (!isInBounds(yard, row, col)) return 0;

    const curPositionString = getPositionString(row, col);
    if (visited.has(curPositionString)) return 0;

    if (yard[row][col] !== TRAIN_CAR) return 0;

    // Process node
    visited.add(curPositionString);
    let trainLength = 1;

    // Recurse on potential neighbors
    // Because trains never touch each other, everything connected
    // to this car belongs to the same train, so a plain flood fill
    // counts exactly one train's cars.
    for (const direction of directions) {
        const [rowChange, colChange] = direction;

        const newRow = row + rowChange;
        const newCol = col + colChange;

        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, every car connected to the
        // neighboring square is in visited, and it hands back how many it
        // added. Trust it, do not trace it. The 1 for this car + each
        // direction's guaranteed count = exactly this function's contract.
        trainLength += getTrainLength(yard, newRow, newCol, visited);
    }

    return trainLength;
};

const longestTrain = (yard) => {
    const numRows = yard.length;
    const numCols = yard[0].length;

    let longestTrainLength = 0;
    const visited = new Set();

    for (let row = 0; row < numRows; row++) {
        for (let col = 0; col < numCols; col++) {
            const curPositionString = getPositionString(row, col);

            if (visited.has(curPositionString)) continue;

            if (yard[row][col] !== TRAIN_CAR) continue;

            // The recursive leap of faith: trust the contract. When this
            // call returns, this whole train is in visited — the loop can
            // never count it again — and `trainLength` is its number of cars.
            // We do not trace inside; we just compare it to the longest so far.
            const trainLength = getTrainLength(yard, row, col, visited);

            longestTrainLength = Math.max(longestTrainLength, trainLength);
        }
    }

    return longestTrainLength;
};

