// CONTRACT for flattenPlaylist(nestedPlaylist, flatSongIds):
//     when this call returns, every song id inside `nestedPlaylist` —
//     including songs buried in folders within folders — has been
//     appended to `flatSongIds`, in exact play order.
const flattenPlaylist = (nestedPlaylist, flatSongIds) => {
    for (const element of nestedPlaylist) {
        // Base case: a plain integer is a song, so record it in play order.
        if (typeof element === 'number') {
            flatSongIds.push(element);
            continue;
        }

        // Recurse on neighbors: an array is a folder, so dive inside it
        // the moment we reach it (this matches the play order).
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, every song inside this
        // folder has been appended to `flatSongIds` in play order. Trust
        // it, do not trace it. Songs recorded directly here + each
        // folder's guaranteed songs, all in the order we meet them —
        // exactly this function's contract, kept.
        flattenPlaylist(element, flatSongIds);
