    const flatSongIds = [];

    // The recursive leap of faith: trust the contract. When this
    // call returns, `flatSongIds` holds every song in the whole
    // playlist in play order. We do not trace inside; we just read
    // off the k-th entry.
    flattenPlaylist(playlist, flatSongIds);

    // Empty folders contribute nothing, so the playlist can hold
